style.css:
@-moz-document domain("roblox.com") {
/* Target the body or main content wrapper for the background */
    body, html, #page-container, .content {
        background: url("https://i.imgur.com/your-image-url-here.jpg") no-repeat center center fixed !important;
        background-size: cover !important; /* Ensures the image covers the entire background */
        background-color: #e0e0f0 !important; /* A fallback light purple if the image doesn't load */
    }

    /* Make sure other elements don't obscure the background */
    /* This might require some trial and error depending on the page */
    .container-main, .section-content, .card {
        background-color: rgba(255, 255, 255, 0.7) !important; /* Make existing containers slightly transparent */
        /* Or set to transparent if you want your background image to show through more */
        /* background-color: transparent !important; */
    }

    /* Remove specific background colors from elements that might cover your image */
    .left-col, .right-col {
        background-color: transparent !important;
    }

    /* You might need to make other specific elements transparent too */
    /* For example, if there's a white header or footer */
    .topbar, .footer {
        background-color: rgba(255, 255, 255, 0.5) !important; /* Adjust transparency as desired */
    }

    /* Example to make the top bar clearer if it covers your background */
    .topbar .container-fluid {
        background-color: transparent !important;
    }
}
